/** Returns a validated cloned command; only a native human-browsing HTTP(S) navigation is admitted. */
function validateCommand(input, snapshot) {
  byteLimit(input,16000,'Browser command');
  const value=object(input,['type','tabId','url','zoom','text','forward','findNext','browserProfileId','action','kind','targetTabId','query','index','anchor','id','toastId','stars','side','floor','label','holds','keys','pin','dismiss','float','material','still','level','ignoreCache'],'Browser command',['type','tabId']);
  id(value.tabId,'Command tab');/* A tab card that is going away (the pointer left, a press or a key ended it) names the tab it showed, and that tab may be the one that just closed under the pointer: nothing is left to look up, and refusing it only logged a bridge error. */if(!(value.type==='tab-card'&&(value.action==='leave'||value.action==='dismiss')))reference(snapshot,'tabs',value.tabId,'Command tab');
  const shape=(keys,required=[])=>object(value,['type','tabId',...keys],`Command ${value.type}`,['type','tabId',...required]);
  switch(value.type) {
    case 'edge':{shape(['holds','keys','pin','dismiss','float','forward','material','still']);if(has(value,'still'))oneOf(value.still,['take','park','hold','release'],'Page picture step');if(has(value,'material')){const m=object(value.material,['regions','duration','reveal'],'Desktop material',['regions','duration','reveal']);if(!Array.isArray(m.regions)||m.regions.length<2||m.regions.length>6)fail('Desktop material requires toolbar, sidebar and up to four page cut-outs');for(const row of m.regions){object(row,['x','y','width','height','radius'],'Material rectangle',['x','y','width','height','radius']);for(const key of ['x','y','width','height','radius'])number(row[key],0,20000,'Material '+key);}number(m.duration,0,2000,'Material duration');boolean(m.reveal,'Material reveal');}if(has(value,'float'))boolean(value.float,'Floating chrome');if(has(value,'forward')){const f=object(value.forward,['type','x','y','button','clickCount','deltaX','deltaY','tabId'],'Forwarded input',['type','x','y']);if(has(f,'tabId')&&(typeof f.tabId!=='string'||!f.tabId||f.tabId.length>200))fail('Forwarded pane');oneOf(f.type,['mouseDown','mouseUp','mouseWheel'],'Forwarded input type');number(f.x,-1,20000,'Forwarded x');number(f.y,-1,20000,'Forwarded y');if(has(f,'button'))oneOf(f.button,['left','middle','right'],'Forwarded button');if(has(f,'clickCount'))number(f.clickCount,1,3,'Click count');for(const key of ['deltaX','deltaY'])if(has(f,key))number(f[key],-20000,20000,'Wheel delta');}if(!['holds','keys','pin','dismiss','float','forward','material','still'].some(key=>has(value,key)))fail('An edge command names its holds, keys, a pin or a dismissal');for(const key of ['holds','keys'])if(has(value,key)){const flags=object(value[key],['top','side'],'Edge '+key,['top','side']);boolean(flags.top,'Top '+key);boolean(flags.side,'Side '+key);}if(has(value,'dismiss'))oneOf(value.dismiss,['top','side'],'Edge zone');if(has(value,'pin')){const pin=object(value.pin,['zone','on'],'Edge pin',['zone','on']);oneOf(pin.zone,['top','side'],'Edge zone');boolean(pin.on,'Pinned');}break;}
    case 'window-control':shape(['action'],['action']);oneOf(value.action,['close','exit-fullscreen'],'Window control');break;
    case 'address-highlight':shape(['query','index'],['query','index']);text(value.query,4096,'Address suggestion query');number(value.index,-1,7,'Address suggestion index',true);break;
    case 'navigate':shape(['url'],['url']);webURL(value.url,'Navigation URL');break;
    case 'print':case 'save-page':case 'save-pdf':case 'back':case 'forward':case 'stop':case 'focus':case 'focus-page':case 'devtools':case 'stop-find':case 'clear-data':case 'stop-capture':case 'snapshot':shape([]);break;
    case 'reload':shape(['ignoreCache']);if(has(value,'ignoreCache'))boolean(value.ignoreCache,'Ignore cache');break;
    case 'zoom':shape(['zoom'],['zoom']);number(value.zoom,25,500,'Page zoom');break;
    case 'context-run':shape(['id'],['id']);text(value.id,200,'Context menu item');break;
    case 'find':shape(['text','forward','findNext'],['text']);text(value.text,4096,'Find text');for(const key of ['forward','findNext'])if(has(value,key))boolean(value[key],key);break;
    case 'media':shape(['action','level'],['action']);oneOf(value.action,['toggle','play','pause','volume'],'Media action');if(has(value,'level')){if(value.action!=='volume')fail('Only a volume command carries a level');number(value.level,0,1,'Volume level');}break;
    case 'tab-card':shape(['action','anchor','side','floor','label'],['action']);if(has(value,'label')){const named=object(value.label,['title','host'],'Tab card label',['title','host']);text(named.title,300,'Tab card title');text(named.host,300,'Tab card address');}oneOf(value.action,['hover','leave','dismiss'],'Tab card action');if(value.action==='hover'&&!has(value,'anchor'))fail('A tab card needs the box of its tab');if(has(value,'anchor'))bounds(value.anchor,'Tab card anchor');if(has(value,'side'))oneOf(value.side,['below','right','left'],'Tab card side');if(has(value,'floor'))number(value.floor,0,12000,'Tab card floor');break;
    case 'profile':shape(['browserProfileId'],['browserProfileId']);id(value.browserProfileId,'Browser profile');reference(snapshot,'browserProfiles',value.browserProfileId,'Browser profile');break;
    case 'ui':shape(['action','kind','targetTabId','anchor','toastId','stars'],['action']);if(has(value,'toastId')&&(value.action!=='toast-dismiss'||!Number.isSafeInteger(value.toastId)||value.toastId<0))fail('Only a toast dismissal names a toast row');if(value.action==='rating-submit'?!Number.isInteger(value.stars)||value.stars<1||value.stars>5:has(value,'stars'))fail('Only a rating answer names its stars, 1 to 5');oneOf(value.action,['open','split','find','focus-mode','seamless-mode','address-commit','popup-trigger','rename-group','rename-tab','favorite-tab','preview-hold','preview-dismiss','customize-sidebar','reader','toast-dismiss','toast-hold','toast-release','rating-hold','rating-dismiss','rating-submit'],'UI action');if(has(value,'anchor'))bounds(value.anchor,'UI anchor');if(has(value,'kind'))oneOf(value.kind,overlayKinds,'Popup kind');if(value.action==='open'&&!has(value,'kind'))fail('Opening a popup requires its kind');if(value.action==='popup-trigger'&&(!has(value,'anchor')||has(value,'kind')||has(value,'targetTabId')))fail('Popup trigger forwarding requires only its pointer bounds');if(has(value,'targetTabId')&&value.targetTabId!==''){id(value.targetTabId,'Target tab');reference(snapshot,'tabs',value.targetTabId,'Target tab');}break;
    default:fail('Unknown browser command');
  }
  const result=structuredClone(value);if(result.targetTabId==='')delete result.targetTabId;return result;
}

const bounds=(value,label)=>{object(value,['x','y','width','height'],label,['x','y','width','height']);for(const key of ['x','y','width','height'])number(value[key],0,12000,`${label}.${key}`);};
