  if(has(value,'pageBounds'))bounds(value.pageBounds,'Page card bounds');if(has(value,'pageRadius'))number(value.pageRadius,0,40,'Page card radius');if(has(value,'pageImmediate'))boolean(value.pageImmediate,'Measured page geometry');if(has(value,'pageMotion'))oneOf(value.pageMotion,['slide'],'Page motion');if(has(value,'pageSpring')){const spring=object(value.pageSpring,['duration','bounce'],'Page spring',['duration','bounce']);number(spring.duration,.05,3,'Page spring duration');number(spring.bounce,0,.95,'Page spring bounce');}if(has(value,'pageHold'))boolean(value.pageHold,'Page hold');if(has(value,'pageEdgeLag')){const lag=object(value.pageEdgeLag,['x','y'],'Page edge lag');if(has(lag,'x'))number(lag.x,0,600,'Page left and right edge lag');if(has(lag,'y'))number(lag.y,0,600,'Page top and bottom edge lag');}if(has(value,'edge')){const edge=object(value.edge,['topHeight','sideWidth'],'Edge sizes',['topHeight','sideWidth']);number(edge.topHeight,0,400,'Top chrome height');number(edge.sideWidth,0,600,'Side chrome width');}
